REVOKE EXECUTE ON FUNCTION org_score_snapshot(uuid,text),org_store_score(uuid,jsonb,jsonb,jsonb,jsonb,text,text) FROM authenticated;
GRANT EXECUTE ON FUNCTION org_score_snapshot(uuid,text) TO service_role;
CREATE FUNCTION public.org_server_score_snapshot(aid uuid,actor uuid,item text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb;BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Server action required';END IF;PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);result:=org_score_snapshot(aid,item);RETURN result;END $$;
CREATE FUNCTION public.org_server_store_score(aid uuid,actor uuid,expected jsonb,rs jsonb,recs jsonb,sc jsonb,st text,item text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result boolean;BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Server action required';END IF;PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);result:=org_store_score(aid,expected,rs,recs,sc,st,item);RETURN result;END $$;
REVOKE ALL ON FUNCTION org_server_score_snapshot(uuid,uuid,text),org_server_store_score(uuid,uuid,jsonb,jsonb,jsonb,jsonb,text,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION org_server_score_snapshot(uuid,uuid,text),org_server_store_score(uuid,uuid,jsonb,jsonb,jsonb,jsonb,text,text) TO service_role;
CREATE FUNCTION public.org_test_rule(rule text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF rule='candidate_retention' THEN RETURN (SELECT column_default='12' FROM information_schema.columns WHERE table_schema='public' AND table_name='org_settings' AND column_name='retention_months');ELSIF rule='blind_scoring' THEN RETURN NOT has_function_privilege('authenticated','public.org_score_snapshot(uuid,text)','EXECUTE') AND NOT has_function_privilege('authenticated','public.org_store_score(uuid,jsonb,jsonb,jsonb,jsonb,text,text)','EXECUTE') AND has_function_privilege('authenticated','public.org_blind_work(uuid)','EXECUTE');ELSIF rule='candidate_not_user' THEN RETURN NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='assessment_attempts' AND column_name='user_id');ELSIF rule='people_not_deleted' THEN RETURN NOT has_table_privilege('authenticated','public.org_people','DELETE');ELSIF rule='org_rls' THEN RETURN NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('org_people','org_person_roles','org_assignments','org_settings','org_invitations','assessment_rater_assignments','hiring_decisions') AND NOT c.relrowsecurity);END IF;RETURN false;END $$;
REVOKE ALL ON FUNCTION org_test_rule(text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION org_test_rule(text) TO service_role;